def remove_parentheses(s):
    stack = []
    result = []

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')' and stack:
            start = stack.pop()
            result.append(s[start + 1:i])

    return ''.join(result)

