    # Iterate through the tokens
    for i in range(1, len(tokens), 2):
        operator = tokens[i]
        next_number = int(tokens[i + 1])

        # Handle special cases
        if operator == '/' and next_number == 0:
            return None
        elif operator == '^' and next_number == 0:
            return 0

        # Apply the operation
        if operator == '+':
            result += next_number
        elif operator == '-':
            result -= next_number
        elif operator == '*':
            result *= next_number
        elif operator == '/':
            result //= next_number
        elif operator == '^':
            result **= next_number

    return result

