def remove_parentheses(s):
    result = []
    depth = 0
    skip = False

    for char in s:
        if char == '(':
            depth += 1
            skip = True
        elif char == ')':
            depth -= 1
            if depth == 0:
                skip = False
        elif not skip:
            result.append(char)

    return ''.join(result)

